// Specialize by composing, not extending
function WelcomeDialog() {
  return <Dialog title="Welcome" body={<p>Thanks for joining!</p>} />;
}

function Dialog({ title, body, actions }) {
  return <div>{title && <header>{title}</header>}<main>{body}</main><footer>{actions}</footer></div>;
}

function UserCardContainer() {
  const user = useUser();
  return <UserCard name={user.name} avatar={user.avatar} />;
}

function Toggle({ children }) {
  const [open, setOpen] = useState(false);
  return <div>{open && children}</div>; // children not re-created on toggle
}

