solution.code:
function Card({ header, children, footer }) {
  return (
    <div style={{ border: '1px solid #ccc', borderRadius: 8, fontFamily: 'system-ui', width: 260, overflow: 'hidden' }}>
      {header && <div style={{ padding: 12, fontWeight: 700, borderBottom: '1px solid #eee' }}>{header}</div>}
      <div style={{ padding: 12 }}>{children}</div>
      {footer && <div style={{ padding: 12, borderTop: '1px solid #eee', textAlign: 'right' }}>{footer}</div>}
    </div>
  );
}

function App() {
  return (
    <div style={{ padding: 16 }}>
      <Card
        header="Profile"
        footer={<button>Edit</button>}
      >
        <p style={{ margin: 0 }}>Composition lets this Card stay generic.</p>
      </Card>
    </div>
  );
}

