function Panel({ header, children, footer }) {
  return (
    <div style={{ border: '1px solid #ccc', borderRadius: 8, overflow: 'hidden', fontFamily: 'system-ui' }}>
      {header && <div style={{ padding: 12, fontWeight: 700, borderBottom: '1px solid #eee' }}>{header}</div>}
      <div style={{ padding: 12 }}>{children}</div>
      {footer && <div style={{ padding: 12, borderTop: '1px solid #eee' }}>{footer}</div>}
    </div>
  );
}

function App() {
